const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.append(renderer.domElement);
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

const globe = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 48),
  new THREE.MeshStandardMaterial({ color: 0x3d8fd1, roughness: 0.45, metalness: 0.1 }),
);
const pivot = new THREE.Group();
pivot.add(globe);
scene.add(pivot);

scene.add(new THREE.HemisphereLight(0xeaf2ff, 0x1a1520, 1.2));
const key = new THREE.DirectionalLight(0xfff2d6, 1.4);
key.position.set(3, 4, 2);
scene.add(key);
camera.position.set(0, 0.4, 4);
camera.lookAt(0, 0, 0);

const render = () => renderer.render(scene, camera);
gsap.ticker.add(render);
addEventListener('beforeunload', () => gsap.ticker.remove(render));

const sun = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 24), new THREE.MeshBasicMaterial({ color: 0xffc56b }));
scene.add(sun);
const orbit = new THREE.Group();
globe.position.set(2.4, 0, 0);
orbit.add(globe);
scene.add(orbit);
gsap.to(orbit.rotation, { y: Math.PI * 2, duration: 12, ease: 'none', repeat: -1 });

gsap.to(camera.position, {
  x: 0.6, y: 0.35, z: 3.4,
  duration: 3,
  ease: 'power2.inOut',
  onUpdate: () => camera.lookAt(0, 0, 0),
});

const intro = gsap.timeline();
intro.from(globe.scale, { x: 0.2, y: 0.2, z: 0.2, duration: 0.8, ease: 'power3.out' }, 0);
intro.to(camera.position, { z: 3.2, duration: 1.4, ease: 'power2.inOut' }, 0.2);
intro.to(globe.rotation, { y: 0.6, duration: 1.6, ease: 'power2.out' }, 0.6);

gsap.from(meshes.map((mesh) => mesh.scale), {
  x: 0, y: 0, z: 0,
  duration: 0.7,
  stagger: 0.08,
  ease: 'back.out(1.4)',
});

const fresnel = new THREE.ShaderMaterial({
  uniforms: { color: { value: new THREE.Color(0x4ea3ff) } },
  vertexShader: `varying vec3 vN; varying vec3 vV; void main(){ vN = normalize(normalMatrix * normal); vec4 p = modelViewMatrix * vec4(position,1.0); vV = normalize(-p.xyz); gl_Position = projectionMatrix * p; }`,
  fragmentShader: `uniform vec3 color; varying vec3 vN; varying vec3 vV; void main(){ float f = pow(1.0 - max(dot(vN, vV), 0.0), 2.4); gl_FragColor = vec4(color * (0.25 + f), 1.0); }`,
});

const iridescence = new THREE.ShaderMaterial({
  uniforms: { a: { value: new THREE.Color(0x66f0c8) }, b: { value: new THREE.Color(0xb48cff) } },
  vertexShader: `varying float vF; void main(){ vec3 n = normalize(normalMatrix * normal); vec4 p = modelViewMatrix * vec4(position,1.0); vF = pow(1.0 - abs(dot(n, normalize(-p.xyz))), 1.8); gl_Position = projectionMatrix * p; }`,
  fragmentShader: `uniform vec3 a; uniform vec3 b; varying float vF; void main(){ gl_FragColor = vec4(mix(a, b, vF), 1.0); }`,
});

const warp = new THREE.ShaderMaterial({
  uniforms: { time: { value: 0 }, color: { value: new THREE.Color(0x9fe870) } },
  vertexShader: `uniform float time; varying float vD; void main(){ float d = sin(position.y * 6.0 + time) * 0.06; vD = d; vec3 p = position + normal * d; gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0); }`,
  fragmentShader: `uniform vec3 color; varying float vD; void main(){ gl_FragColor = vec4(color * (0.8 + vD * 2.0), 1.0); }`,
});
gsap.to(warp.uniforms.time, { value: Math.PI * 2, duration: 6, repeat: -1, ease: 'none' });

const shell = new THREE.MeshPhysicalMaterial({
  color: 0xb9e7ff,
  roughness: 0.18,
  metalness: 0.05,
  clearcoat: 0.7,
  clearcoatRoughness: 0.2,
});

const glass = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.9,
  thickness: 0.35,
  roughness: 0.08,
  ior: 1.4,
  transparent: true,
});

const sunMat = new THREE.MeshStandardMaterial({
  color: 0xffb347,
  emissive: 0xff8a2b,
  emissiveIntensity: 2.2,
  roughness: 0.4,
});

const haze = new THREE.Mesh(
  new THREE.SphereGeometry(1.06, 48, 32),
  new THREE.MeshBasicMaterial({ color: 0x7ecbff, transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, side: THREE.BackSide }),
);
globe.add(haze);

scene.add(new THREE.HemisphereLight(0xc9e4ff, 0x241820, 0.7));
const key = new THREE.DirectionalLight(0xffe1b5, 1.6);
key.position.set(2.5, 3, 1.5);
scene.add(key);

const sunLight = new THREE.PointLight(0xffd18a, 8, 12, 2);
sunLight.position.set(0, 0, 0);
scene.add(sunLight);
// globe.position is on an orbit group; do not add sunLight to that group

const rim = new THREE.DirectionalLight(0x9ad7ff, 0.55);
rim.position.set(-3, 0.5, -2);
scene.add(rim);

const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
addEventListener('pointermove', (event) => {
  pointer.x = (event.clientX / innerWidth) * 2 - 1;
  pointer.y = -(event.clientY / innerHeight) * 2 + 1;
  raycaster.setFromCamera(pointer, camera);
  const hit = raycaster.intersectObject(globe).length > 0;
  gsap.to(globe.scale, { x: hit ? 1.06 : 1, y: hit ? 1.06 : 1, z: hit ? 1.06 : 1, duration: 0.25, ease: 'power2.out' });
});

const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
if (!reduce) {
  gsap.to(camera.position, { z: 3.2, duration: 3, ease: 'power2.inOut' });
}

addEventListener('message', (event) => {
  const data = event.data;
  if (!data || data.type !== 'scene-foundry:controls') return;
  const controls = data.controls ?? {};
  if (typeof controls.speed === 'number') gsap.globalTimeline.timeScale(controls.speed);
  if (typeof controls.hue === 'number') renderer.domElement.style.filter = `hue-rotate(${controls.hue}deg)`;
  if (typeof controls.wireframe === 'boolean') {
    scene.traverse((obj) => { if (obj.isMesh) obj.material.wireframe = controls.wireframe; });
  }
});

function disposeMesh(mesh) {
  mesh.geometry.dispose();
  const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
  for (const mat of mats) mat.dispose();
}

renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

await document.fonts.ready;
const source = document.querySelector('[data-webgl-text]');
if (source) {
  const visual = new Text();
  visual.text = source.textContent?.trim() ?? '';
  visual.font = '/fonts/display.woff2';
  visual.sync();
  syncVisualBounds(visual, source.getBoundingClientRect());
}

const state = { reveal: 0 };
const transition = gsap.to(state, {
  reveal: 1,
  duration: 0.65,
  ease: 'power3.inOut',
  paused: true,
  onUpdate: () => { material.uniforms.uReveal.value = state.reveal; },
});
card.addEventListener('pointerenter', () => transition.play());
card.addEventListener('pointerleave', () => transition.reverse());

gsap.to(material.uniforms.uProgress, {
  value: 1,
  ease: 'none',
  scrollTrigger: {
    trigger: section,
    start: 'top top',
    end: 'bottom top',
    scrub: true,
  },
});

const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduceMotion) {
  intro.progress(1).pause();
} else {
  intro.play();
}
pauseButton.addEventListener('click', () => {
  timeline.paused(!timeline.paused());
});

const stopListening = events.on('input:activate', (payload) => {
  scene.activate(payload.id);
});

function destroy() {
  stopListening();
}
